USE DATABASE OBS;

-- helper: Last successful harvest per account, snapshot source and day; IS_LATEST marks the current state.
CREATE OR REPLACE VIEW OBS.CURATED.SNAPSHOT_HARVEST
  COMMENT = 'Last successful harvest per account, snapshot source and day; IS_LATEST marks the current state.'
AS
SELECT
  ACCOUNT_NAME,
  SOURCE_TABLE,
  SNAPSHOT_DATE,
  HARVEST_ID,
  SNAPSHOT_DATE = MAX(SNAPSHOT_DATE) OVER (PARTITION BY ACCOUNT_NAME, SOURCE_TABLE) AS IS_LATEST
FROM (
  SELECT
    ACCOUNT_NAME,
    SOURCE_TABLE,
    CAST(AS_OF AS DATE) AS SNAPSHOT_DATE,
    HARVEST_ID
  FROM RAW.HARVEST_LOG
  WHERE
    STATUS = 'ok' AND STRATEGY = 'full_snapshot'
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY ACCOUNT_NAME, SOURCE_TABLE, CAST(AS_OF AS DATE)
      ORDER BY AS_OF DESC NULLS LAST, HARVEST_ID DESC NULLS LAST
    ) = 1
) AS s;

