SELECT
  h.SNAPSHOT_DATE,
  h.IS_LATEST,
  r.ACCOUNT_NAME,
  r.REPORT_ID,
  r.TOOL,
  r.NAME,
  r.WORKSPACE,
  r.OWNER,
  r.DATASET,
  r.STRUCTURE_HASH,
  r.QUERY_PARAMETERIZED_HASH,
  r.VIEWS_90D,
  r.REFRESHES_PER_DAY,
  r.LAST_VIEWED,
  r.CREATED
FROM CURATED.SNAPSHOT_HARVEST AS h
JOIN RAW.SNAPSHOT_MEMBERSHIP AS m
  ON m.ACCOUNT_NAME = h.ACCOUNT_NAME
  AND m.SOURCE_TABLE = h.SOURCE_TABLE
  AND m.HARVEST_ID = h.HARVEST_ID
JOIN RAW.BI_REPORTS AS r
  ON r.ACCOUNT_NAME = m.ACCOUNT_NAME AND r._ROW_HASH = m.ROW_HASH
WHERE
  h.SOURCE_TABLE = 'BI_REPORTS';

-- snapshot: Daily snapshots of BI_MEASURES reconstructed from RAW membership.
CREATE OR REPLACE VIEW OBS.CURATED.SNAP_BI_MEASURES
  COMMENT = 'Daily snapshots of BI_MEASURES reconstructed from RAW membership.'
AS
SELECT
  h.SNAPSHOT_DATE,
  h.IS_LATEST,
  r.ACCOUNT_NAME,
  r.REPORT_ID,
  r.KPI_NAME,
  r.EXPRESSION,
  r.SOURCE_COLUMNS
FROM CURATED.SNAPSHOT_HARVEST AS h
JOIN RAW.SNAPSHOT_MEMBERSHIP AS m
  ON m.ACCOUNT_NAME = h.ACCOUNT_NAME
  AND m.SOURCE_TABLE = h.SOURCE_TABLE
  AND m.HARVEST_ID = h.HARVEST_ID
JOIN RAW.BI_MEASURES AS r
  ON r.ACCOUNT_NAME = m.ACCOUNT_NAME AND r._ROW_HASH = m.ROW_HASH
WHERE
  h.SOURCE_TABLE = 'BI_MEASURES';

-- dim: Latest client-supplied inputs (contract price, commitments, SLAs, tag names). VALUE is JSON text.
CREATE OR REPLACE VIEW OBS.CURATED.CFG_CLIENT_INPUT
  COMMENT = 'Latest client-supplied inputs (contract price, commitments, SLAs, tag names). VALUE is JSON text.'
AS
SELECT
  ACCOUNT_NAME,
  KEY,
  VALUE,
  TRIM(VALUE, '"') AS VALUE_TEXT
FROM CURATED.SNAP_CLIENT_INPUTS
WHERE
  IS_LATEST;

-- dim: One row per harvested account with contract price and capacity commitment.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_ACCOUNT
  COMMENT = 'One row per harvested account with contract price and capacity commitment.'
AS
SELECT
  a.ACCOUNT_NAME,
  a.ORGANIZATION_NAME,
  a.REGION,
  a.EDITION,
  a.NETWORK_POLICY,
  MAX(CASE WHEN c.KEY = 'contract_price_per_credit' THEN CAST(c.VALUE AS DOUBLE) END) AS PRICE_PER_CREDIT,
  MAX(CASE WHEN c.KEY = 'storage_price_per_tb_month' THEN CAST(c.VALUE AS DOUBLE) END) AS STORAGE_PRICE_PER_TB_MONTH,
  MAX(
    CASE
      WHEN c.KEY = 'capacity_commitment'
      THEN CAST(JSON_EXTRACT_PATH_TEXT(c.VALUE, 'annual_credits') AS DOUBLE)
    END
  ) AS ANNUAL_COMMIT_CREDITS,
  MAX(
    CASE
      WHEN c.KEY = 'capacity_commitment'
      THEN CAST(JSON_EXTRACT_PATH_TEXT(c.VALUE, 'start_date') AS DATE)
    END
  ) AS COMMIT_START,
  MAX(
    CASE
      WHEN c.KEY = 'capacity_commitment'
      THEN CAST(JSON_EXTRACT_PATH_TEXT(c.VALUE, 'end_date') AS DATE)
    END
  ) AS COMMIT_END,
  MAX(CASE WHEN c.KEY = 'cost_center_tag' THEN c.VALUE_TEXT END) AS COST_CENTRE_TAG,
  MAX(CASE WHEN c.KEY = 'owner_tag' THEN c.VALUE_TEXT END) AS OWNER_TAG
FROM CURATED.SNAP_ACCOUNT_INFO AS a
LEFT JOIN CURATED.CFG_CLIENT_INPUT AS c
  ON c.ACCOUNT_NAME = a.ACCOUNT_NAME
WHERE
  a.IS_LATEST
GROUP BY
  a.ACCOUNT_NAME,
  a.ORGANIZATION_NAME,
  a.REGION,
  a.EDITION,
  a.NETWORK_POLICY;

-- dim: Calendar spine covering the archived metering history.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_DAY
  COMMENT = 'Calendar spine covering the archived metering history.'
AS
WITH b AS (SELECT MIN(START_TIME::DATE) AS lo, MAX(START_TIME::DATE) AS hi FROM RAW.WAREHOUSE_METERING_HISTORY) SELECT DATEADD(DAY, g.n, b.lo) AS DAY, DATE_TRUNC('MONTH', DATEADD(DAY, g.n, b.lo))::DATE AS MONTH,
       DAYOFWEEK(DATEADD(DAY, g.n, b.lo)) AS DOW, DAYOFWEEK(DATEADD(DAY, g.n, b.lo)) IN (0, 6) AS IS_WEEKEND
FROM b, (SELECT ROW_NUMBER() OVER (ORDER BY SEQ4()) - 1 AS n FROM TABLE(GENERATOR(ROWCOUNT => 3660))) g WHERE DATEADD(DAY, g.n, b.lo) <= b.hi;

-- dim: Current tag assignments.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_TAG
  COMMENT = 'Current tag assignments.'
AS
SELECT
  ACCOUNT_NAME,
  TAG_NAME,
  TAG_VALUE,
  DOMAIN,
  OBJECT_DATABASE,
  OBJECT_SCHEMA,
  OBJECT_NAME,
  COLUMN_NAME,
  CASE
    WHEN OBJECT_DATABASE IS NULL
    THEN OBJECT_NAME
    ELSE OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME
  END AS OBJECT_FQ_NAME
FROM CURATED.SNAP_TAG_REFERENCES
WHERE
  IS_LATEST;

-- dim: Current warehouses with their cost-centre tag (UNALLOCATED when untagged).
CREATE OR REPLACE VIEW OBS.CURATED.DIM_WAREHOUSE
  COMMENT = 'Current warehouses with their cost-centre tag (UNALLOCATED when untagged).'
AS
SELECT
  w.ACCOUNT_NAME,
  w.WAREHOUSE_NAME,
  w.WAREHOUSE_SIZE,
  w.AUTO_SUSPEND,
  w.MIN_CLUSTER_COUNT,
  w.MAX_CLUSTER_COUNT,
  w.SCALING_POLICY,
  w.RESOURCE_MONITOR,
  w.WORKLOAD_CLASS,
  w.OWNER,
  COALESCE(t.TAG_VALUE, 'UNALLOCATED') AS COST_CENTRE
FROM CURATED.SNAP_WAREHOUSES AS w
LEFT JOIN CURATED.DIM_ACCOUNT AS a
  ON a.ACCOUNT_NAME = w.ACCOUNT_NAME
LEFT JOIN (
  SELECT
    ACCOUNT_NAME,
    TAG_NAME,
    OBJECT_NAME,
    MAX(TAG_VALUE) AS TAG_VALUE
  FROM CURATED.DIM_TAG
  WHERE
    DOMAIN = 'WAREHOUSE'
  GROUP BY
    1,
    2,
    3
) AS t
  ON t.ACCOUNT_NAME = w.ACCOUNT_NAME
  AND t.OBJECT_NAME = w.WAREHOUSE_NAME
  AND t.TAG_NAME = COALESCE(a.COST_CENTRE_TAG, 'COST_CENTER')
WHERE
  w.IS_LATEST;

-- dim: Cost centres (from warehouse tags) plus the UNALLOCATED bucket.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_COST_CENTRE
  COMMENT = 'Cost centres (from warehouse tags) plus the UNALLOCATED bucket.'
AS
SELECT DISTINCT
  ACCOUNT_NAME,
  COST_CENTRE
FROM CURATED.DIM_WAREHOUSE
UNION
SELECT
  ACCOUNT_NAME,
  'UNALLOCATED' AS COST_CENTRE
FROM CURATED.DIM_ACCOUNT;

-- dim: Current users; IS_HUMAN for PERSON (or untyped) users; IS_ACCOUNTADMIN when granted ACCOUNTADMIN.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_USER
  COMMENT = 'Current users; IS_HUMAN for PERSON (or untyped) users; IS_ACCOUNTADMIN when granted ACCOUNTADMIN.'
AS
SELECT
  u.ACCOUNT_NAME,
  u.NAME AS USER_NAME,
  u.TYPE,
  COALESCE(u.TYPE, 'PERSON') = 'PERSON' AS IS_HUMAN,
  u.HAS_PASSWORD,
  u.HAS_MFA,
  u.HAS_RSA_PUBLIC_KEY,
  NOT u.EXT_AUTHN_UID IS NULL AS IS_SSO,
  u.DISABLED,
  u.CREATED_ON,
  u.LAST_SUCCESS_LOGIN,
  u.NETWORK_POLICY,
  u.DEFAULT_ROLE,
  COALESCE(g.IS_ADMIN, FALSE) AS IS_ACCOUNTADMIN
FROM CURATED.SNAP_USERS AS u
LEFT JOIN (
  SELECT
    ACCOUNT_NAME,
    GRANTEE_NAME,
    TRUE AS IS_ADMIN
  FROM CURATED.SNAP_GRANTS_TO_USERS
  WHERE
    IS_LATEST AND ROLE = 'ACCOUNTADMIN'
  GROUP BY
    1,
    2
) AS g
  ON g.ACCOUNT_NAME = u.ACCOUNT_NAME AND g.GRANTEE_NAME = u.NAME
WHERE
  u.IS_LATEST;

-- dim: Current roles with the number of users and roles they are granted to.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_ROLE
  COMMENT = 'Current roles with the number of users and roles they are granted to.'
AS
SELECT
  r.ACCOUNT_NAME,
  r.NAME AS ROLE_NAME,
  r.ROLE_TYPE,
  r.OWNER,
  r.NAME IN ('ACCOUNTADMIN', 'SECURITYADMIN', 'SYSADMIN', 'USERADMIN', 'ORGADMIN', 'PUBLIC') AS IS_SYSTEM,
  (
    SELECT
      COUNT(*)
    FROM CURATED.SNAP_GRANTS_TO_USERS AS gu
    WHERE
      gu.IS_LATEST AND gu.ACCOUNT_NAME = r.ACCOUNT_NAME AND gu.ROLE = r.NAME
  ) AS USER_GRANTS,
  (
    SELECT
      COUNT(*)
    FROM CURATED.SNAP_GRANTS_TO_ROLES AS gr
    WHERE
      gr.IS_LATEST
      AND gr.ACCOUNT_NAME = r.ACCOUNT_NAME
      AND gr.GRANTED_ON = 'ROLE'
      AND gr.NAME = r.NAME
  ) AS ROLE_GRANTS
FROM CURATED.SNAP_ROLES AS r
WHERE
  r.IS_LATEST;

-- fact: Object access events (reads and writes) from ACCESS_HISTORY.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_ACCESS
  COMMENT = 'Object access events (reads and writes) from ACCESS_HISTORY.'
AS
SELECT DISTINCT
  ACCOUNT_NAME,
  QUERY_ID,
  QUERY_START_TIME,
  CAST(QUERY_START_TIME AS DATE) AS DAY,
  USER_NAME,
  OBJECT_NAME,
  OBJECT_DOMAIN,
  ACCESS_TYPE
FROM RAW.ACCESS_HISTORY;

-- dim: Current tables with tier, owner tag, comment flag and last recorded access.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_OBJECT
  COMMENT = 'Current tables with tier, owner tag, comment flag and last recorded access.'
AS
SELECT
  t.ACCOUNT_NAME,
  t.FQ_NAME,
  t.TABLE_CATALOG,
  t.TABLE_SCHEMA,
  t.TABLE_NAME,
  t.TABLE_TYPE,
  t.IS_TRANSIENT,
  t.BYTES,
  t.ROW_COUNT,
  t.RETENTION_TIME,
  t.CREATED,
  t.LAST_ALTERED,
  NOT t.COMMENT IS NULL AS HAS_COMMENT,
  COALESCE(tier.TAG_VALUE, 'untiered') AS TIER,
  COALESCE(tier.TAG_VALUE, '') = 'tier1' AS IS_TIER1,
  own.TAG_VALUE AS OWNER_TAG_VALUE,
  acc.LAST_ACCESSED
FROM CURATED.SNAP_TABLES AS t
LEFT JOIN CURATED.DIM_ACCOUNT AS a
  ON a.ACCOUNT_NAME = t.ACCOUNT_NAME
LEFT JOIN (
  SELECT
    ACCOUNT_NAME,
    OBJECT_FQ_NAME,
    MAX(TAG_VALUE) AS TAG_VALUE
  FROM CURATED.DIM_TAG
  WHERE
    DOMAIN = 'TABLE' AND TAG_NAME = 'TIER'
  GROUP BY
    1,
    2
) AS tier
  ON tier.ACCOUNT_NAME = t.ACCOUNT_NAME AND tier.OBJECT_FQ_NAME = t.FQ_NAME
LEFT JOIN (
  SELECT
    ACCOUNT_NAME,
    TAG_NAME,
    OBJECT_FQ_NAME,
    MAX(TAG_VALUE) AS TAG_VALUE
  FROM CURATED.DIM_TAG
  WHERE
    DOMAIN = 'TABLE'
  GROUP BY
    1,
    2,
    3
) AS own
  ON own.ACCOUNT_NAME = t.ACCOUNT_NAME
  AND own.OBJECT_FQ_NAME = t.FQ_NAME
  AND own.TAG_NAME = COALESCE(a.OWNER_TAG, 'DATA_OWNER')
LEFT JOIN (
  SELECT
    ACCOUNT_NAME,
    OBJECT_NAME,
    MAX(QUERY_START_TIME) AS LAST_ACCESSED
  FROM CURATED.FACT_ACCESS
  GROUP BY
    1,
    2
) AS acc
  ON acc.ACCOUNT_NAME = t.ACCOUNT_NAME AND acc.OBJECT_NAME = t.FQ_NAME
WHERE
  t.IS_LATEST;

-- dim: Current tasks with their target table and whether it is Tier-1.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_TASK
  COMMENT = 'Current tasks with their target table and whether it is Tier-1.'
AS
SELECT
  k.ACCOUNT_NAME,
  k.FQ_NAME,
  k.TASK_NAME,
  k.DATABASE_NAME,
  k.SCHEMA_NAME,
  k.OWNER,
  k.WAREHOUSE,
  k.SCHEDULE,
  k.PREDECESSORS,
  k.STATE,
  k.TARGET_TABLE,
  COALESCE(o.IS_TIER1, FALSE) AS IS_TIER1
FROM CURATED.SNAP_TASKS AS k
LEFT JOIN CURATED.DIM_OBJECT AS o
  ON o.ACCOUNT_NAME = k.ACCOUNT_NAME AND o.FQ_NAME = k.TARGET_TABLE
WHERE
  k.IS_LATEST;

-- fact: Billing truth — latest restatement of METERING_DAILY_HISTORY per account, day and service type.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_METERING_DAILY
  COMMENT = 'Billing truth — latest restatement of METERING_DAILY_HISTORY per account, day and service type.'
AS
SELECT
  ACCOUNT_NAME,
  USAGE_DATE AS DAY,
  SERVICE_TYPE,
  CREDITS_USED_COMPUTE,
  CREDITS_USED_CLOUD_SERVICES,
  CREDITS_USED,
  CREDITS_ADJUSTMENT_CLOUD_SERVICES,
  CREDITS_BILLED
FROM RAW.METERING_DAILY_HISTORY
QUALIFY
  ROW_NUMBER() OVER (
    PARTITION BY ACCOUNT_NAME, USAGE_DATE, SERVICE_TYPE
    ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
  ) = 1;

-- fact: Hourly warehouse metering joined to load (latest restatement per hour).
CREATE OR REPLACE VIEW OBS.CURATED.FACT_WAREHOUSE_HOURLY
  COMMENT = 'Hourly warehouse metering joined to load (latest restatement per hour).'
AS
SELECT
  m.ACCOUNT_NAME,
  m.WAREHOUSE_NAME,
  m.START_TIME,
  CAST(m.START_TIME AS DATE) AS DAY,
  m.CREDITS_USED,
  m.CREDITS_USED_COMPUTE,
  m.CREDITS_USED_CLOUD_SERVICES,
  l.AVG_RUNNING,
  l.AVG_QUEUED_LOAD
FROM (
  SELECT
    *
  FROM RAW.WAREHOUSE_METERING_HISTORY
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY ACCOUNT_NAME, WAREHOUSE_NAME, START_TIME
      ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
    ) = 1
) AS m
LEFT JOIN (
  SELECT
    *
  FROM RAW.WAREHOUSE_LOAD_HISTORY
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY ACCOUNT_NAME, WAREHOUSE_NAME, START_TIME
      ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
    ) = 1
) AS l
  ON l.ACCOUNT_NAME = m.ACCOUNT_NAME
  AND l.WAREHOUSE_NAME = m.WAREHOUSE_NAME
  AND l.START_TIME = m.START_TIME;

-- fact: Compute credits attributed to each query.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_QUERY_ATTRIBUTION
  COMMENT = 'Compute credits attributed to each query.'
AS
SELECT
  ACCOUNT_NAME,
  QUERY_ID,
  WAREHOUSE_NAME,
  QUERY_PARAMETERIZED_HASH,
  QUERY_TAG,
  USER_NAME,
  START_TIME,
  CAST(START_TIME AS DATE) AS DAY,
  CREDITS_ATTRIBUTED_COMPUTE
FROM RAW.QUERY_ATTRIBUTION_HISTORY
QUALIFY
  ROW_NUMBER() OVER (
    PARTITION BY ACCOUNT_NAME, QUERY_ID
    ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
  ) = 1;

-- fact: Daily warehouse credits. CREDITS_BILLED allocates the account-day cloud-services adjustment from METERING_DAILY_HISTORY pro rata to each warehouses cloud-services credits, so warehouse cost reconciles to billing. IDLE_CREDITS = compute credits not attributed to any query.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_WAREHOUSE_DAILY
  COMMENT = 'Daily warehouse credits. CREDITS_BILLED allocates the account-day cloud-services adjustment from METERING_DAILY_HISTORY pro rata to each warehouses cloud-services credits, so warehouse cost reconciles to billing. IDLE_CREDITS = compute credits not at'
AS
WITH h AS (
  SELECT
    ACCOUNT_NAME,
    WAREHOUSE_NAME,
    DAY,
    SUM(CREDITS_USED) AS CREDITS_USED,
    SUM(CREDITS_USED_COMPUTE) AS CREDITS_USED_COMPUTE,
    SUM(CREDITS_USED_CLOUD_SERVICES) AS CREDITS_USED_CLOUD_SERVICES,
    COUNT(*) AS ACTIVE_HOURS,
    AVG(AVG_RUNNING) AS AVG_RUNNING,
    AVG(AVG_QUEUED_LOAD) AS AVG_QUEUED_LOAD
  FROM CURATED.FACT_WAREHOUSE_HOURLY
  GROUP BY
    1,
    2,
    3
), tot AS (
  SELECT
    ACCOUNT_NAME,
    DAY,
    SUM(CREDITS_USED_CLOUD_SERVICES) AS CLOUD
  FROM h
  GROUP BY
    1,
    2
), adj AS (
  SELECT
    ACCOUNT_NAME,
    DAY,
    SUM(CREDITS_ADJUSTMENT_CLOUD_SERVICES) AS ADJ
  FROM CURATED.FACT_METERING_DAILY
  WHERE
    SERVICE_TYPE = 'WAREHOUSE_METERING'
  GROUP BY
    1,
    2
), att AS (
  SELECT
    ACCOUNT_NAME,
    WAREHOUSE_NAME,
    DAY,
    SUM(CREDITS_ATTRIBUTED_COMPUTE) AS ATTRIBUTED
  FROM CURATED.FACT_QUERY_ATTRIBUTION
  GROUP BY
    1,
    2,
    3
)
SELECT
  h.ACCOUNT_NAME,
  h.WAREHOUSE_NAME,
  h.DAY,
  h.CREDITS_USED,
  h.CREDITS_USED_COMPUTE,
  h.CREDITS_USED_CLOUD_SERVICES,
  COALESCE(adj.ADJ, 0) * CASE WHEN tot.CLOUD > 0 THEN h.CREDITS_USED_CLOUD_SERVICES / tot.CLOUD ELSE 0 END AS CREDITS_ADJUSTMENT_ALLOCATED,
  h.CREDITS_USED + COALESCE(adj.ADJ, 0) * CASE WHEN tot.CLOUD > 0 THEN h.CREDITS_USED_CLOUD_SERVICES / tot.CLOUD ELSE 0 END AS CREDITS_BILLED,
  LEAST_IGNORE_NULLS(COALESCE(att.ATTRIBUTED, 0), h.CREDITS_USED_COMPUTE) AS CREDITS_ATTRIBUTED,
  h.CREDITS_USED_COMPUTE - LEAST_IGNORE_NULLS(COALESCE(att.ATTRIBUTED, 0), h.CREDITS_USED_COMPUTE) AS IDLE_CREDITS,
  h.ACTIVE_HOURS,
  h.AVG_RUNNING,
  h.AVG_QUEUED_LOAD,
  w.COST_CENTRE
FROM h
JOIN tot
  ON tot.ACCOUNT_NAME = h.ACCOUNT_NAME AND tot.DAY = h.DAY
LEFT JOIN adj
  ON adj.ACCOUNT_NAME = h.ACCOUNT_NAME AND adj.DAY = h.DAY
LEFT JOIN att
  ON att.ACCOUNT_NAME = h.ACCOUNT_NAME
  AND att.WAREHOUSE_NAME = h.WAREHOUSE_NAME
  AND att.DAY = h.DAY
LEFT JOIN CURATED.DIM_WAREHOUSE AS w
  ON w.ACCOUNT_NAME = h.ACCOUNT_NAME AND w.WAREHOUSE_NAME = h.WAREHOUSE_NAME;

-- fact: Serverless and AI credits by service type and object (service types match METERING_DAILY_HISTORY).
CREATE OR REPLACE VIEW OBS.CURATED.FACT_SERVERLESS_DAILY
  COMMENT = 'Serverless and AI credits by service type and object (service types match METERING_DAILY_HISTORY).'
AS
SELECT
  ACCOUNT_NAME,
  CAST(START_TIME AS DATE) AS DAY,
  'AUTO_CLUSTERING' AS SERVICE_TYPE,
  TABLE_NAME AS OBJECT_NAME,
  SUM(CREDITS_USED) AS CREDITS
FROM RAW.AUTOMATIC_CLUSTERING_HISTORY
GROUP BY
  1,
  2,
  3,
  4
UNION ALL
SELECT
  ACCOUNT_NAME,
  CAST(START_TIME AS DATE),
  'SEARCH_OPTIMIZATION',
  TABLE_NAME,
  SUM(CREDITS_USED)
FROM RAW.SEARCH_OPTIMIZATION_HISTORY
GROUP BY
  1,
  2,
  3,
  4
UNION ALL
SELECT
  ACCOUNT_NAME,
  CAST(START_TIME AS DATE),
  'MATERIALIZED_VIEW',
  TABLE_NAME,
  SUM(CREDITS_USED)
FROM RAW.MATERIALIZED_VIEW_REFRESH_HISTORY
GROUP BY
  1,
  2,
  3,
  4
UNION ALL
SELECT
  ACCOUNT_NAME,
  CAST(START_TIME AS DATE),
  'PIPE',
  PIPE_NAME,
  SUM(CREDITS_USED)
FROM RAW.PIPE_USAGE_HISTORY
GROUP BY
  1,
  2,
  3,
  4
UNION ALL
SELECT
  ACCOUNT_NAME,
  CAST(START_TIME AS DATE),
  'AI_SERVICES',
  FUNCTION_NAME,
  SUM(TOKEN_CREDITS)
FROM RAW.CORTEX_USAGE_HISTORY
GROUP BY
  1,
  2,
  3,
  4;

-- fact: Queries with signature, timings, scan/spill/pruning metrics and attributed credits.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_QUERY
  COMMENT = 'Queries with signature, timings, scan/spill/pruning metrics and attributed credits.'
AS
SELECT
  q.ACCOUNT_NAME,
  q.QUERY_ID,
  CAST(q.START_TIME AS DATE) AS DAY,
  q.START_TIME,
  q.END_TIME,
  COALESCE(q.QUERY_PARAMETERIZED_HASH, '(none)') AS SIGNATURE,
  q.QUERY_TYPE,
  q.DATABASE_NAME,
  q.USER_NAME,
  q.ROLE_NAME,
  q.WAREHOUSE_NAME,
  q.WAREHOUSE_SIZE,
  q.QUERY_TAG,
  q.EXECUTION_STATUS,
  COALESCE(q.CLIENT_APPLICATION_ID, 'UNKNOWN') AS CLIENT_APPLICATION,
  q.TOTAL_ELAPSED_TIME,
  q.EXECUTION_TIME,
  q.QUEUED_OVERLOAD_TIME,
  q.COMPILATION_TIME,
  q.BYTES_SCANNED,
  q.PERCENTAGE_SCANNED_FROM_CACHE,
  q.PARTITIONS_SCANNED,
  q.PARTITIONS_TOTAL,
  q.BYTES_SPILLED_TO_LOCAL_STORAGE,
  q.BYTES_SPILLED_TO_REMOTE_STORAGE,
  q.CREDITS_USED_CLOUD_SERVICES,
  COALESCE(a.CREDITS_ATTRIBUTED_COMPUTE, 0) AS CREDITS_ATTRIBUTED_COMPUTE
FROM (
  SELECT
    *
  FROM RAW.QUERY_HISTORY
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY ACCOUNT_NAME, QUERY_ID
      ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
    ) = 1
) AS q
LEFT JOIN CURATED.FACT_QUERY_ATTRIBUTION AS a
  ON a.ACCOUNT_NAME = q.ACCOUNT_NAME AND a.QUERY_ID = q.QUERY_ID;

-- dim: Parameterised query signatures with a sample text and activity window.
CREATE OR REPLACE VIEW OBS.CURATED.DIM_QUERY_SIGNATURE
  COMMENT = 'Parameterised query signatures with a sample text and activity window.'
AS
SELECT
  q.ACCOUNT_NAME,
  q.QUERY_PARAMETERIZED_HASH AS SIGNATURE,
  MIN(q.QUERY_TEXT) AS SAMPLE_TEXT,
  MIN(q.START_TIME) AS FIRST_SEEN,
  MAX(q.START_TIME) AS LAST_SEEN,
  COUNT(*) AS EXECUTIONS,
  MIN(q.WAREHOUSE_NAME) AS WAREHOUSE_NAME
FROM RAW.QUERY_HISTORY AS q
WHERE
  NOT q.QUERY_PARAMETERIZED_HASH IS NULL
GROUP BY
  1,
  2;

-- fact: Task runs (latest state per run and attempt) with the Tier-1 flag of the target table.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_TASK_RUN
  COMMENT = 'Task runs (latest state per run and attempt) with the Tier-1 flag of the target table.'
AS
SELECT
  r.ACCOUNT_NAME,
  r.FQ_NAME,
  r.NAME AS TASK_NAME,
  r.STATE,
  r.ERROR_CODE,
  r.ERROR_MESSAGE,
  r.SCHEDULED_TIME,
  CAST(r.SCHEDULED_TIME AS DATE) AS DAY,
  r.QUERY_START_TIME,
  r.COMPLETED_TIME,
  r.RUN_ID,
  r.ATTEMPT_NUMBER,
  COALESCE(t.IS_TIER1, FALSE) AS IS_TIER1,
  t.TARGET_TABLE
FROM (
  SELECT
    *
  FROM RAW.TASK_HISTORY
  QUALIFY
    ROW_NUMBER() OVER (
      PARTITION BY ACCOUNT_NAME, FQ_NAME, RUN_ID, ATTEMPT_NUMBER
      ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
    ) = 1
) AS r
LEFT JOIN CURATED.DIM_TASK AS t
  ON t.ACCOUNT_NAME = r.ACCOUNT_NAME AND t.FQ_NAME = r.FQ_NAME;

-- fact: Freshness SLA outcome per Tier-1 table and day (client SLAs joined to the loading tasks runs).
CREATE OR REPLACE VIEW OBS.CURATED.FACT_FRESHNESS
  COMMENT = 'Freshness SLA outcome per Tier-1 table and day (client SLAs joined to the loading tasks runs).'
AS
WITH sla AS (
  SELECT c.ACCOUNT_NAME, f.value:"table"::STRING AS TABLE_NAME, f.value:"loaded_by"::STRING AS LOADED_BY,
         f.value:"deadline_utc"::STRING AS DEADLINE_UTC
  FROM CURATED.CFG_CLIENT_INPUT c, LATERAL FLATTEN(input => PARSE_JSON(c.VALUE)) f
  WHERE c.KEY = 'freshness_slas'),
runs AS (
  SELECT ACCOUNT_NAME, FQ_NAME, DAY, MAX(CASE WHEN STATE = 'SUCCEEDED' THEN COMPLETED_TIME END) AS LOADED_AT
  FROM CURATED.FACT_TASK_RUN GROUP BY 1, 2, 3)
SELECT r.ACCOUNT_NAME, r.DAY, sla.TABLE_NAME, sla.LOADED_BY,
       TO_TIMESTAMP(r.DAY::STRING || ' ' || sla.DEADLINE_UTC, 'YYYY-MM-DD HH24:MI') AS DEADLINE_TS, r.LOADED_AT,
       r.LOADED_AT IS NOT NULL AND r.LOADED_AT <= TO_TIMESTAMP(r.DAY::STRING || ' ' || sla.DEADLINE_UTC, 'YYYY-MM-DD HH24:MI') AS MET
FROM sla JOIN runs r ON r.ACCOUNT_NAME = sla.ACCOUNT_NAME AND r.FQ_NAME = sla.LOADED_BY;

-- fact: Login attempts.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_LOGIN
  COMMENT = 'Login attempts.'
AS
SELECT
  ACCOUNT_NAME,
  EVENT_ID,
  EVENT_TIMESTAMP,
  CAST(EVENT_TIMESTAMP AS DATE) AS DAY,
  USER_NAME,
  CLIENT_IP,
  REPORTED_CLIENT_TYPE,
  FIRST_AUTHENTICATION_FACTOR,
  SECOND_AUTHENTICATION_FACTOR,
  IS_SUCCESS = 'YES' AS IS_SUCCESS,
  ERROR_CODE,
  ERROR_MESSAGE
FROM RAW.LOGIN_HISTORY
QUALIFY
  ROW_NUMBER() OVER (
    PARTITION BY ACCOUNT_NAME, EVENT_ID
    ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
  ) = 1;

-- fact: Account storage by day.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_STORAGE_DAILY
  COMMENT = 'Account storage by day.'
AS
SELECT
  ACCOUNT_NAME,
  USAGE_DATE AS DAY,
  STORAGE_BYTES,
  STAGE_BYTES,
  FAILSAFE_BYTES,
  HYBRID_TABLE_STORAGE_BYTES
FROM RAW.STORAGE_USAGE
QUALIFY
  ROW_NUMBER() OVER (
    PARTITION BY ACCOUNT_NAME, USAGE_DATE
    ORDER BY _LOADED_AT DESC NULLS LAST, _HARVEST_ID DESC NULLS LAST
  ) = 1;

-- fact: Cortex function and agent usage.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_CORTEX_USAGE
  COMMENT = 'Cortex function and agent usage.'
AS
SELECT
  ACCOUNT_NAME,
  START_TIME,
  END_TIME,
  CAST(START_TIME AS DATE) AS DAY,
  FUNCTION_NAME,
  MODEL_NAME,
  COALESCE(AGENT_NAME, '(no agent)') AS AGENT_NAME,
  AGENT_NAME IS NULL AS NO_AGENT,
  ROLE_NAME,
  USER_NAME,
  TOKENS,
  TOKEN_CREDITS
FROM RAW.CORTEX_USAGE_HISTORY;

-- fact: Data metric function results.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_DQ_RESULT
  COMMENT = 'Data metric function results.'
AS
SELECT
  ACCOUNT_NAME,
  MEASUREMENT_TIME,
  CAST(MEASUREMENT_TIME AS DATE) AS DAY,
  TABLE_NAME,
  METRIC_NAME,
  VALUE,
  COALESCE(EXPECTATION_VIOLATED, FALSE) AS EXPECTATION_VIOLATED
FROM RAW.DATA_QUALITY_MONITORING_RESULTS;

-- fact: Bulk and Snowpipe file loads.
CREATE OR REPLACE VIEW OBS.CURATED.FACT_COPY
  COMMENT = 'Bulk and Snowpipe file loads.'
AS
SELECT
  ACCOUNT_NAME,
  FILE_NAME,
  TABLE_NAME,
  PIPE_NAME,
  LAST_LOAD_TIME,
  CAST(LAST_LOAD_TIME AS DATE) AS DAY,
  ROW_COUNT,
  ERROR_COUNT,
  STATUS
FROM RAW.COPY_HISTORY;

-- fact: Harvest runs per source (Section 7.8 service levels).
CREATE OR REPLACE VIEW OBS.CURATED.FACT_HARVEST
  COMMENT = 'Harvest runs per source (Section 7.8 service levels).'
AS
SELECT
  ACCOUNT_NAME,
  HARVEST_ID,
  SOURCE_TABLE,
  STRATEGY,
  AS_OF,
  CAST(AS_OF AS DATE) AS DAY,
  ROWS_READ,
  ROWS_INSERTED,
  ROWS_DUPLICATE,
  STATUS,
  ERROR
FROM RAW.HARVEST_LOG;
